descriptor.templateCss:
/* ── Root ─────────────────────────────────────────────────────────────── */
.sp-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  font-family: Roboto, sans-serif;
  font-size: 13px;
  color: var(--sp-fg, #212121);
  background: transparent;
  overflow: hidden;
}

/* ── Toolbar ─────────────────────────────────────────────────────────────── */
.sp-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: transparent;
  border-bottom: 1px solid var(--sp-border, #e0e0e0);
  flex-shrink: 0;
}
.sp-logo-icon { font-size: 20px; color: #5c6bc0; }
.sp-logo-text  { font-size: 14px; font-weight: 500; color: var(--sp-fg, #212121); }
.sp-grow       { flex: 1; }

/* Health dot */
.sp-health   { display: flex; align-items: center; gap: 5px; font-size: 12px; color: #757575; }
.sp-dot      { width: 9px; height: 9px; border-radius: 50%; background: #bdbdbd; transition: background .4s; }
.sp-dot.ok   { background: #43a047; }
.sp-dot.err  { background: #e53935; }

/* Icon button */
.sp-ibtn {
  background: none; border: none; cursor: pointer; padding: 4px;
  border-radius: 4px; color: #757575; display: flex; align-items: center;
  transition: background .15s;
}
.sp-ibtn:hover { background: rgba(0,0,0,.06); }

/* ── Controls bar ────────────────────────────────────────────────────────── */
.sp-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  background: transparent;
  border-bottom: 1px solid var(--sp-border, #e0e0e0);
  flex-shrink: 0;
}
.sp-ctrl-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.sp-ctrl-label {
  font-size: 11px;
  color: #757575;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.sp-input {
  height: 28px;
  border: 1px solid #ccc;
  border-radius: 4px;
  padding: 0 8px;
  font-size: 13px;
  background: var(--sp-input-bg, #fff);
  color: var(--sp-fg, #212121);
  width: 100px;
  outline: none;
  transition: border-color .15s;
}
.sp-input:focus { border-color: #5c6bc0; }
.sp-input-sm   { width: 70px; }
.sp-fw         { width: 100%; box-sizing: border-box; }

/* Primary run button */
.sp-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  transition: background .15s, opacity .15s;
}
.sp-btn-run {
  background: #5c6bc0;
  color: #fff;
}
.sp-btn-run:hover   { background: #3f51b5; }
.sp-btn-run:disabled { opacity: .5; cursor: not-allowed; }
.sp-btn:not(.sp-btn-run) { background: #e0e0e0; color: #424242; }
.sp-btn:not(.sp-btn-run):hover { background: #bdbdbd; }

/* Source badge */
.sp-badge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 10px;
  background: #e8eaf6;
  color: #3f51b5;
  font-weight: 500;
}
.sp-elapsed { font-size: 12px; color: #9e9e9e; }

/* ── Empty state ─────────────────────────────────────────────────────────── */
.sp-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #bdbdbd;
}
.sp-empty mat-icon { font-size: 48px; width: 48px; height: 48px; }
.sp-empty p        { font-size: 13px; color: #9e9e9e; text-align: center; }

/* ── Results ─────────────────────────────────────────────────────────────── */
#results {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 12px 4px;
  overflow-y: auto;
  min-height: 0;
}

/* KPI cards */
.sp-kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  flex-shrink: 0;
}
.sp-kpi {
  background: var(--sp-card-bg, #fff);
  border: 1px solid var(--sp-border, #e0e0e0);
  border-radius: 6px;
  padding: 10px 14px;
  text-align: center;
}
.sp-kpi-warn { border-top: 3px solid #fb8c00; }
.sp-kpi-info { border-top: 3px solid #039be5; }
.sp-kpi-val  { font-size: 22px; font-weight: 600; color: #3f51b5; line-height: 1.2; }
.sp-kpi-lbl  { font-size: 11px; color: #757575; margin-top: 3px; }

/* Charts row */
.sp-charts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  flex-shrink: 0;
}
.sp-chart-card {
  background: var(--sp-card-bg, #fff);
  border: 1px solid var(--sp-border, #e0e0e0);
  border-radius: 6px;
  padding: 8px;
}
.sp-chart-title {
  font-size: 12px;
  font-weight: 500;
  color: #616161;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.sp-chart { height: 140px; }

/* Section / table */
.sp-section { flex-shrink: 0; }
.sp-section-title {
  font-size: 11px;
  font-weight: 600;
  color: #9e9e9e;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 4px;
}
.sp-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.sp-tbl th {
  text-align: left;
  padding: 5px 10px;
  background: var(--sp-th-bg, #f5f5f5);
  border: 1px solid var(--sp-border, #e0e0e0);
  font-weight: 500;
  color: #616161;
}
.sp-tbl td {
  padding: 5px 10px;
  border: 1px solid var(--sp-border, #e0e0e0);
  color: var(--sp-fg, #212121);
}
.sp-tbl tr:hover td { background: rgba(92,107,192,.05); }
.sp-tag { display:inline-block; padding:1px 6px; border-radius:10px; font-size:11px; font-weight:500; }
.sp-tag-idle { background:#e8f5e9; color:#2e7d32; }
.sp-tag-busy { background:#fff3e0; color:#e65100; }
.sp-tag-queue{ background:#fce4ec; color:#c62828; }

/* ── Status bar ──────────────────────────────────────────────────────────── */
.sp-status {
  padding: 3px 12px;
  font-size: 11px;
  color: #9e9e9e;
  min-height: 18px;
  flex-shrink: 0;
  border-top: 1px solid var(--sp-border, #e0e0e0);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sp-status.err { color: #e53935; }
.sp-status.ok  { color: #43a047; }

/* ── Modal ───────────────────────────────────────────────────────────────── */
.sp-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.35);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}
.sp-dlg {
  background: var(--sp-card-bg, #fff);
  border-radius: 8px;
  padding: 20px 24px;
  width: 340px;
  box-shadow: 0 8px 24px rgba(0,0,0,.18);
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.sp-dlg-title {
  display: flex; align-items: center; gap: 6px;
  font-size: 15px; font-weight: 500;
}
.sp-lbl { display: flex; flex-direction: column; gap: 4px; font-size: 13px; }
.sp-hint { font-size: 11px; color: #9e9e9e; }
.sp-dlg-ft { display: flex; justify-content: flex-end; gap: 8px; }

/* ── Dark mode ───────────────────────────────────────────────────────────── */
.sp-root.dark .sp-toolbar     { border-color: #333; }
.sp-root.dark .sp-controls    { border-color: #333; }
.sp-root.dark .sp-ctrl-label  { color: #9e9e9e; }
.sp-root.dark .sp-input       { border-color: #555; color: #e0e0e0; background: #2a2a2a; }
.sp-root.dark .sp-ibtn        { color: #aaa; }
.sp-root.dark .sp-ibtn:hover  { background: rgba(255,255,255,.08); }
.sp-root.dark .sp-btn:not(.sp-btn-run) { background: #333; color: #ccc; }
.sp-root.dark .sp-kpi         { background: #1e1e1e; border-color: #333; }
.sp-root.dark .sp-kpi-val     { color: #9fa8da; }
.sp-root.dark .sp-kpi-lbl     { color: #757575; }
.sp-root.dark .sp-chart-card  { background: #1e1e1e; border-color: #333; }
.sp-root.dark .sp-chart-title { color: #757575; }
.sp-root.dark .sp-section-title { color: #757575; }
.sp-root.dark .sp-tbl th      { background: #252525; border-color: #333; color: #9e9e9e; }
.sp-root.dark .sp-tbl td      { background: #1e1e1e; border-color: #333; color: #e0e0e0; }
.sp-root.dark .sp-tbl tr:hover td { background: #252525; }
.sp-root.dark .sp-tag-idle    { background: #1b3a1f; color: #81c784; }
.sp-root.dark .sp-tag-busy    { background: #3e2600; color: #ffb74d; }
.sp-root.dark .sp-tag-queue   { background: #3b0e14; color: #e57373; }
.sp-root.dark .sp-badge       { background: #1a237e; color: #9fa8da; }
.sp-root.dark .sp-elapsed     { color: #616161; }
.sp-root.dark .sp-status      { border-color: #333; color: #616161; }
.sp-root.dark .sp-status.ok   { color: #66bb6a; }
.sp-root.dark .sp-status.err  { color: #ef5350; }
.sp-root.dark .sp-empty p     { color: #616161; }
.sp-root.dark .sp-dlg         { background: #252525; color: #e0e0e0; }
.sp-root.dark .sp-lbl         { color: #e0e0e0; }
.sp-root.dark .sp-hint        { color: #616161; }
.sp-root.dark .sp-logo-text   { color: #e0e0e0; }
.sp-root.dark .sp-health      { color: #757575; }
.sp-root.dark #results        { background: transparent; }

descriptor.controllerScript:
/* ======================================================
   SimPy Line 2 — Simulation Runner
   ThingsBoard static widget

   RESOURCES required:
     https://cdn.jsdelivr.net/npm/echarts@5/dist/echarts.min.js

   SETTINGS:
     serverBaseUrl  — e.g. http://localhost:9000
   ====================================================== */

let _cycleChart = null;
let _powerChart = null;
let _healthTimer = null;
let _runStart = null;

const st = {
  BASE: "http://localhost:9000",
  lastResult: null,
};

/* ── DOM helper ───────────────────────────────────────── */
function $q(sel) {
  return self.ctx.$container[0].querySelector(sel);
}

function isDark() {
  return !!document
    .querySelector(".tb-dashboard-page")
    ?.classList.contains("dark");
}

function applyTheme() {
  const root = $q(".sp-root");
  if (root) root.classList.toggle("dark", isDark());
}

/* ── Settings (persist via localStorage / window top) ── */
const LS_KEY = "simpy_widget_settings";

function getTop() { try { return window.top || window; } catch (_) { return window; } }
function getMem()  { const t = getTop(); if (!t._spw) t._spw = {}; return t._spw; }
function getLS()   {
  try { const l = getTop().localStorage; l.getItem("_"); return l; } catch (_) {}
  try { const l = window.localStorage;   l.getItem("_"); return l; } catch (_) {}
  return null;
}
function storeRead() {
  const m = getMem();
  if (m.serverBaseUrl) return m;
  const ls = getLS();
  if (ls) { try { const d = JSON.parse(ls.getItem(LS_KEY) || "{}"); if (d.serverBaseUrl) return d; } catch (_) {} }
  return {};
}
function storeWrite(obj) {
  Object.assign(getMem(), obj);
  const ls = getLS();
  if (ls) { try { ls.setItem(LS_KEY, JSON.stringify(Object.assign({}, getMem(), obj))); } catch (_) {} }
}

function loadSettings() {
  const s    = self.ctx.settings || {};
  const st_s = storeRead();
  st.BASE = ((st_s.serverBaseUrl || s.serverBaseUrl || "http://localhost:9000")).replace(/\/+$/, "");
}

function openSettings() {
  $q("#cfgUrl").value = st.BASE;
  $q("#settingsModal").style.display = "flex";
}
function closeSettings() { $q("#settingsModal").style.display = "none"; }
function saveSettings() {
  const url = ($q("#cfgUrl").value || "").replace(/\/+$/, "").trim();
  if (!url) return;
  st.BASE = url;
  storeWrite({ serverBaseUrl: url });
  closeSettings();
  setStatus("Settings saved — " + url, "ok");
  checkHealth();
}

/* ── Status bar ───────────────────────────────────────── */
function setStatus(msg, level) {
  const el = $q("#statusBar");
  if (!el) return;
  el.textContent = msg;
  el.className = "sp-status" + (level ? " " + level : "");
}

/* ── Health check ─────────────────────────────────────── */
async function checkHealth() {
  const dot  = $q("#healthDot");
  const text = $q("#healthText");
  try {
    const r = await fetch(st.BASE + "/health", { signal: AbortSignal.timeout(4000) });
    const ok = r.ok;
    if (dot)  { dot.className  = "sp-dot " + (ok ? "ok" : "err"); }
    if (text) { text.textContent = ok ? "API connected" : "API error " + r.status; }
  } catch (_) {
    if (dot)  { dot.className  = "sp-dot err"; }
    if (text) { text.textContent = "Unreachable"; }
  }
}

/* ── Run simulation ────────────────────────────────────── */
async function runSim() {
  const btn     = $q("#runBtn");
  const simTime = parseFloat($q("#simTimeInput").value) || 28000;
  const seed    = parseInt($q("#seedInput").value)      || 42;

  btn.disabled = true;
  btn.innerHTML = "<mat-icon>hourglass_empty</mat-icon><span>Running…</span>";
  $q("#emptyState").style.display = "flex";
  $q("#emptyIcon").textContent = "hourglass_empty";
  $q("#emptyMsg").innerHTML = "Simulation running… <b>" + simTime.toLocaleString() + " s</b>";
  $q("#results").style.display = "none";
  $q("#configBadge").style.display = "none";
  setStatus("Sending POST /sim/run …");
  _runStart = Date.now();

  try {
    const r = await fetch(st.BASE + "/sim/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sim_time: simTime, random_seed: seed }),
    });

    if (!r.ok) {
      let detail = r.statusText;
      try { detail = (await r.json()).detail || detail; } catch (_) {}
      throw new Error("HTTP " + r.status + ": " + detail);
    }

    const data = await r.json();
    st.lastResult = data;

    const elapsed = ((Date.now() - _runStart) / 1000).toFixed(2);
    $q("#elapsed").textContent = "took " + elapsed + " s";
    $q("#elapsed").style.display = "";

    renderResults(data);
    setStatus("Simulation complete — sim_time=" + simTime + " s, seed=" + seed, "ok");
  } catch (e) {
    setStatus("Error: " + e.message, "err");
    $q("#emptyIcon").textContent = "error_outline";
    $q("#emptyMsg").textContent  = "Error: " + e.message;
  } finally {
    btn.disabled = false;
    btn.innerHTML = "<mat-icon>play_arrow</mat-icon><span>Run Simulation</span>";
  }
}

/* ── Render results ────────────────────────────────────── */
function fmt(v, decimals) {
  if (v === undefined || v === null) return "—";
  const n = parseFloat(v);
  if (isNaN(n)) return "—";
  return decimals !== undefined ? n.toFixed(decimals) : n.toLocaleString();
}

function renderResults(data) {
  const sink2 = data.sink2 || {};
  const rs    = data.final_resource_state || {};

  // KPI cards
  $q("#kpiThroughput").textContent = fmt(sink2.throughput_per_hour, 1);
  $q("#kpiArrivals").textContent   = fmt(sink2.arrivals);
  $q("#kpiCycleAvg").textContent   = fmt(sink2.cycle_time_avg, 1);
  $q("#kpiPowerAvg").textContent   = fmt(sink2.power_avg, 0);

  // Source badge
  const badge = $q("#configBadge");
  badge.textContent     = "config: " + (data.config_source || "defaults");
  badge.style.display   = "";

  // Charts
  renderCycleChart(sink2);
  renderPowerChart(sink2);

  // Resource table
  const tbody = $q("#resourceTbody");
  tbody.innerHTML = "";
  for (const [name, s] of Object.entries(rs)) {
    let tag;
    if (s.queue > 0)     { tag = '<span class="sp-tag sp-tag-queue">queued (' + s.queue + ')</span>'; }
    else if (s.busy > 0) { tag = '<span class="sp-tag sp-tag-busy">busy</span>'; }
    else                 { tag = '<span class="sp-tag sp-tag-idle">idle</span>'; }
    tbody.innerHTML +=
      "<tr><td>" + name + "</td><td>" + s.busy + "</td><td>" + s.queue + "</td><td>" + tag + "</td></tr>";
  }

  // Show results, hide empty
  $q("#emptyState").style.display = "none";
  $q("#results").style.display    = "flex";

  // Resize charts after layout
  setTimeout(() => {
    _cycleChart && _cycleChart.resize();
    _powerChart && _powerChart.resize();
  }, 50);
}

/* ── ECharts helpers ───────────────────────────────────── */
function chartTheme() { return isDark() ? "dark" : "light"; }

function makeBarOption(title, categories, values, color) {
  const theme = isDark();
  return {
    backgroundColor: "transparent",
    grid: { left: 60, right: 16, top: 8, bottom: 24, containLabel: false },
    tooltip: {
      trigger: "axis",
      axisPointer: { type: "shadow" },
      formatter: function(params) {
        return params[0].name + ": <b>" + parseFloat(params[0].value).toLocaleString(undefined, { maximumFractionDigits: 2 }) + "</b>";
      },
    },
    xAxis: {
      type: "value",
      axisLine: { lineStyle: { color: theme ? "#555" : "#ccc" } },
      splitLine: { lineStyle: { color: theme ? "#333" : "#eee" } },
      axisLabel: { fontSize: 10, color: theme ? "#aaa" : "#757575" },
    },
    yAxis: {
      type: "category",
      data: categories,
      axisLabel: { fontSize: 11, color: theme ? "#ccc" : "#424242" },
      axisLine: { lineStyle: { color: theme ? "#555" : "#ccc" } },
    },
    series: [{
      type: "bar",
      data: values,
      barMaxWidth: 24,
      itemStyle: { color: color, borderRadius: [0, 3, 3, 0] },
      label: {
        show: true, position: "right", fontSize: 10,
        color: theme ? "#ccc" : "#424242",
        formatter: function(p) { return parseFloat(p.value).toLocaleString(undefined, { maximumFractionDigits: 1 }); },
      },
    }],
  };
}

function renderCycleChart(sink2) {
  const el = $q("#cycleChart");
  if (!el) return;

  if (!_cycleChart) {
    _cycleChart = echarts.init(el, chartTheme());
  }

  const cats = ["min", "avg", "max", "stdev"];
  const vals = [
    sink2.cycle_time_min   ?? 0,
    sink2.cycle_time_avg   ?? 0,
    sink2.cycle_time_max   ?? 0,
    sink2.cycle_time_stdev ?? 0,
  ];

  _cycleChart.setOption(makeBarOption("Cycle Time", cats, vals, "#5c6bc0"), true);
}

function renderPowerChart(sink2) {
  const el = $q("#powerChart");
  if (!el) return;

  if (!_powerChart) {
    _powerChart = echarts.init(el, chartTheme());
  }

  const cats = ["min", "avg", "max"];
  const vals = [
    sink2.power_min ?? 0,
    sink2.power_avg ?? 0,
    sink2.power_max ?? 0,
  ];

  _powerChart.setOption(makeBarOption("Power", cats, vals, "#039be5"), true);
}

/* ── Lifecycle ─────────────────────────────────────────── */
self.onInit = function () {
  loadSettings();
  applyTheme();

  $q("#runBtn").onclick       = runSim;
  $q("#settingsBtn").onclick  = openSettings;
  $q("#cfgCancel").onclick    = closeSettings;
  $q("#cfgSave").onclick      = saveSettings;

  checkHealth();
  _healthTimer = setInterval(checkHealth, 15000);
};

self.onDestroy = function () {
  if (_healthTimer) clearInterval(_healthTimer);
  if (_cycleChart)  { _cycleChart.dispose(); _cycleChart = null; }
  if (_powerChart)  { _powerChart.dispose(); _powerChart = null; }
};

self.onResize = function () {
  if (_cycleChart) _cycleChart.resize();
  if (_powerChart) _powerChart.resize();
};

descriptor.templateCss:
.sp2-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  font-family: Roboto, sans-serif;
  font-size: 13px;
  color: var(--sp2-fg, #212121);
  background: transparent;
  overflow: hidden;
}

/* Toolbar */
.sp2-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: transparent;
  border-bottom: 1px solid var(--sp2-border, #e0e0e0);
  flex-shrink: 0;
}
.sp2-logo-icon { font-size: 20px; color: #00897b; }
.sp2-logo-text { font-size: 14px; font-weight: 500; }
.sp2-grow      { flex: 1; }

.sp2-health { display:flex; align-items:center; gap:5px; font-size:12px; color:#757575; }
.sp2-dot    { width:9px; height:9px; border-radius:50%; background:#bdbdbd; transition:background .4s; }
.sp2-dot.ok { background:#43a047; }
.sp2-dot.err{ background:#e53935; }

.sp2-ibtn {
  background: none; border: none; cursor: pointer; padding: 4px;
  border-radius: 4px; color: #757575; display: flex; align-items: center;
  transition: background .15s;
}
.sp2-ibtn:hover { background: rgba(0,0,0,.06); }

/* Body */
.sp2-body {
  flex: 1;
  overflow-y: auto;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 0;
}

/* Section */
.sp2-section-title {
  font-size: 11px;
  font-weight: 600;
  color: #9e9e9e;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 5px;
}

/* Tables */
.sp2-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.sp2-tbl th {
  text-align: left;
  padding: 5px 10px;
  background: var(--sp2-th-bg, #f5f5f5);
  border: 1px solid var(--sp2-border, #e0e0e0);
  font-weight: 500;
  color: #616161;
  white-space: nowrap;
}
.sp2-tbl td {
  padding: 5px 10px;
  border: 1px solid var(--sp2-border, #e0e0e0);
  color: var(--sp2-fg, #212121);
}
.sp2-tbl tr:hover td { background: rgba(0,137,123,.05); }
.sp2-val  { font-weight: 600; color: #00695c; }
.sp2-name { font-weight: 500; }
.sp2-param{ color: #757575; }

/* Sensor table spans */
